package areacase

import (
	"math"
	"testing"
)

func TestCircleArea(t *testing.T) {
	got := CircleArea(2)
	want := 3.14159 * 4.0
	if math.Abs(got-want) > 1e-6 {
		t.Fatalf("CircleArea(2) = %v, want %v", got, want)
	}
}

